package com.ilker.microsoftreport;
import org.json.JSONArray;import org.json.JSONObject;import java.util.*;
public final class Models{
 private Models(){}
 public static final class AppSale{public final String appId,appName;public final int quantity;public final double grossUsd,taxUsd;public AppSale(String i,String n,int q,double g,double t){appId=i;appName=n;quantity=q;grossUsd=g;taxUsd=t;}public double netUsd(){return grossUsd-taxUsd;}JSONObject toJson()throws Exception{return new JSONObject().put("appId",appId).put("appName",appName).put("quantity",quantity).put("grossUsd",grossUsd).put("taxUsd",taxUsd);}static AppSale fromJson(JSONObject o){return new AppSale(o.optString("appId",""),o.optString("appName","Bilinmeyen uygulama"),o.optInt("quantity",0),o.optDouble("grossUsd",0),o.optDouble("taxUsd",0));}}
 public static final class Dashboard{public final String businessDate,checkedAt,dataFreshness;public final List<AppSale> sales;public Dashboard(String d,String c,String f,List<AppSale>s){businessDate=d;checkedAt=c;dataFreshness=f==null?"":f;List<AppSale>x=new ArrayList<>(s);x.sort(Comparator.comparingDouble(AppSale::netUsd).reversed().thenComparing(a->a.appName));sales=Collections.unmodifiableList(x);}public int totalQuantity(){int n=0;for(AppSale s:sales)n+=s.quantity;return n;}public double totalGross(){double n=0;for(AppSale s:sales)n+=s.grossUsd;return n;}public double totalTax(){double n=0;for(AppSale s:sales)n+=s.taxUsd;return n;}public double totalNet(){return totalGross()-totalTax();}public String toJson()throws Exception{JSONArray a=new JSONArray();for(AppSale s:sales)a.put(s.toJson());return new JSONObject().put("businessDate",businessDate).put("checkedAt",checkedAt).put("dataFreshness",dataFreshness).put("sales",a).toString();}public static Dashboard fromJson(String j)throws Exception{JSONObject o=new JSONObject(j);JSONArray a=o.optJSONArray("sales");List<AppSale>s=new ArrayList<>();if(a!=null)for(int i=0;i<a.length();i++)s.add(AppSale.fromJson(a.getJSONObject(i)));return new Dashboard(o.optString("businessDate"),o.optString("checkedAt"),o.optString("dataFreshness"),s);}}
}
